<?php $title='Usuarios'; require __DIR__.'/partials/top.php'; $users=[]; try{$st=appDb()->prepare("SELECT u.id,u.name,u.email,u.avatar_path,u.status,tu.role_code,tu.is_owner FROM users u JOIN tenant_users tu ON tu.user_id=u.id WHERE tu.tenant_id=? ORDER BY u.name");$st->execute([$_SESSION['user']['tenant_id']]);$users=$st->fetchAll();}catch(Throwable $e){} $sessions=[]; try{$q=appDb()->prepare("SELECT s.id,s.user_id,s.ip_address,s.user_agent,s.remember_me,s.created_at,s.expires_at,u.name FROM user_sessions s JOIN users u ON u.id=s.user_id JOIN tenant_users tu ON tu.user_id=u.id WHERE tu.tenant_id=? AND s.revoked_at IS NULL AND s.expires_at>NOW() ORDER BY s.created_at DESC");$q->execute([$_SESSION['user']['tenant_id']]);foreach($q->fetchAll() as $ss)$sessions[$ss['user_id']][]=$ss;}catch(Throwable $e){} ?>
